FAMILY = """
    UPDATE "clinical_procedure" p SET family = v.family
      FROM unnest(%(names)s::text[], %(families)s::text[]) AS v(name, family)
     WHERE p.clinic_id = %(clinic)s AND p.section_id = %(section)s AND p.name_ar = v.name AND p.family = ''"""

ADD_PROCEDURE = """
    INSERT INTO "clinical_procedure" (clinic_id, section_id, name_ar, name_en, category, unit, price, typical_min,
                                      typical_max, description, description_en, internal_cost, condition, is_active,
                                      sort, created_at, follow_up, family)
    SELECT %(clinic)s, %(section)s, %(name_ar)s, %(name_en)s, %(category)s, %(unit)s, %(price)s, %(low)s, %(high)s,
           %(description)s, %(description_en)s, 0, %(condition)s, true, %(sort)s, now(), '[]'::jsonb, %(family)s
     WHERE NOT EXISTS (SELECT 1 FROM "clinical_procedure" q WHERE q.clinic_id = %(clinic)s
                          AND q.section_id = %(section)s AND q.name_ar = %(name_ar)s)"""

# clinics.booking_services ADD as written today.
ADD_SERVICE = """
    INSERT INTO "clinics_service" (clinic_id, section_id, name, name_en, kind, price, duration_min, is_active, sort,
                                   procedure_id)
    SELECT p.clinic_id, p.section_id, p.name_ar, p.name_en, 'procedure', p.price, 15, true,
           least(1000 + p.sort, 32000), p.id
      FROM "clinical_procedure" p
     WHERE p.clinic_id = %(clinic)s AND p.is_active
       AND NOT EXISTS (SELECT 1 FROM "clinics_service" m WHERE m.clinic_id = %(clinic)s AND m.procedure_id = p.id)
    ON CONFLICT DO NOTHING"""


def families(apps, schema_editor):
    from core.routing import set_clinic_setting

    alias = schema_editor.connection.alias
    with schema_editor.connection.cursor() as cursor:
        # As clinical 0002: lift forced row-level security for the one read of the places.
        cursor.execute('ALTER TABLE "clinics_clinic" NO FORCE ROW LEVEL SECURITY')
        cursor.execute("SELECT id FROM clinics_clinic ORDER BY id")
        clinics = [row[0] for row in cursor.fetchall()]
        cursor.execute('ALTER TABLE "clinics_clinic" FORCE ROW LEVEL SECURITY')
    names, kinds = [i[0] for i in DENTAL], [i[8] for i in DENTAL]
    for clinic_id in clinics:
        set_clinic_setting(alias, clinic_id)  # row-level security is forced; this transaction only
        with schema_editor.connection.cursor() as cursor:
            cursor.execute("SELECT id FROM clinics_section WHERE clinic_id = %s AND specialty_code = 'dental'", [clinic_id])
            sections = [row[0] for row in cursor.fetchall()]
            for section_id in sections:
                for sort, (ar, en, category, unit, price, low, high, condition, family, text, text_en) in enumerate(DENTAL):
                    cursor.execute(ADD_PROCEDURE, {
                        "clinic": clinic_id, "section": section_id, "name_ar": ar, "name_en": en, "category": category,
                        "unit": unit, "price": price, "low": low, "high": high, "condition": condition, "sort": sort,
                        "family": family, "description": text, "description_en": text_en})
                cursor.execute(FAMILY, {"clinic": clinic_id, "section": section_id, "names": names, "families": kinds})
            if sections:
                cursor.execute(ADD_SERVICE, {"clinic": clinic_id})
    set_clinic_setting(alias, None)



